stats = {'keyword': [8, 10], 'semantic': [3, 4]}  # [engaged, total]
def rate(s):
    e, t = stats[s]
    return round((e + 1) / (t + 2), 3)  # Laplace smoothing
for s in stats: print(s, 'success rate:', rate(s))

